const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  max: 20
});

const typeDefs = gql`
  type User {
    id: ID!
    username: String!
    email: String!
    role: String!
    bio: String
  }

  type Query {
    user(username: String!): User
    searchUsers(filter: String!): [User!]!
  }

  type Mutation {
    updateBio(username: String!, bio: String!): User
    promoteUser(username: String!, newRole: String!): User
  }
`;

// Unicode normalization helper - normalizes to NFC before DB operations
function normalizeInput(input) {
  // NFKC normalization can map different Unicode chars to same ASCII
  // e.g., U+FF07 (fullwidth apostrophe) -> U+0027 (apostrophe)
  // e.g., U+2032 (prime) -> unaffected, but U+FF07 -> '
  return input.normalize('NFKC');
}

const resolvers = {
  Query: {
    user: async (_, { username }) => {
      const normalized = normalizeInput(username);
      // Parameterized query - looks safe
      const result = await pool.query(
        'SELECT id, username, email, role, bio FROM users WHERE username = $1',
        [normalized]
      );
      return result.rows[0] || null;
    },
    searchUsers: async (_, { filter }) => {
      const normalized = normalizeInput(filter);
      // Developer used LIKE with user input after normalization
      // The normalization can introduce SQL metacharacters from Unicode
      const query = `SELECT id, username, email, role, bio FROM users WHERE username LIKE '%${normalized}%' OR bio LIKE '%${normalized}%'`;
      const result = await pool.query(query);
      return result.rows;
    }
  },
  Mutation: {
    updateBio: async (_, { username, bio }) => {
      const normalizedUser = normalizeInput(username);
      const normalizedBio = normalizeInput(bio);
      const result = await pool.query(
        `UPDATE users SET bio = '${normalizedBio}' WHERE username = '${normalizedUser}' RETURNING id, username, email, role, bio`
      );
      return result.rows[0];
    },
    promoteUser: async (_, { username, newRole }) => {
      const normalizedUser = normalizeInput(username);
      const normalizedRole = normalizeInput(newRole);
      // Admin-only operation - but no auth check in code!
      const result = await pool.query(
        `UPDATE users SET role = '${normalizedRole}' WHERE username = '${normalizedUser}' RETURNING id, username, email, role, bio`
      );
      return result.rows[0];
    }
  }
};

const app = express();

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  playground: process.env.NODE_ENV !== 'production'
});

server.applyMiddleware({ app, path: '/graphql' });

app.listen(4000, () => {
  console.log('GraphQL server running on port 4000');
});
